"""Unpack the reviewed CITYHILL-only build and regression tests (SHA-256 checked)."""
from pathlib import Path
import base64,zlib,hashlib,json
DATA=''''''
# Correct transmission substitutions before the immutable checksum check.
DATA=DATA.replace('LFyzCHei','LFyzHei').replace('HeaIqyoK1h','HeaIqyo1h').replace('U2fvro9NWo1r','U2fvro9+1r')
raw=zlib.decompress(base64.b64decode(DATA))
assert hashlib.sha256(raw).hexdigest()=='20c389148a8b2174fe3a7b72ee7f5a8671ed255b65b198095bb30d6f73f07fde'
root=Path(__file__).resolve().parents[1]
files=json.loads(raw)
assert set(files)=={'scripts/build_cityhill643.py','tests/test_cityhill643.py'}
for name,content in files.items():
    path=root/name
    if path.exists():
        continue
    path.parent.mkdir(parents=True,exist_ok=True)
    path.write_text(content)
